/**
 * Shared data contracts for the trace-native component family (M8).
 *
 * `TraceSpan` is the intersection of three real shapes (phoenix ISpanItem,
 * langfuse observation, theo-lens TraceSpanNode — blueprint Corner 2): the
 * smallest type every kit component consumes. Transport fields (tRPC/GraphQL)
 * are deliberately absent. Timestamps accept unix-ns (bigint or numeric
 * string) or an ISO-8601 string — `toNs()` normalizes at the boundary.
 *
 * Note: `bigint` values do not JSON-serialize — story/args tooling must use
 * fixtures directly (EC-2 of the plan).
 */

/** OpenInference / OTel GenAI span-kind vocabulary (subset the kit renders). */
export type SpanKind =
  | "llm"
  | "tool"
  | "retriever"
  | "embedding"
  | "agent"
  | "chain"
  | "reranker"
  | "evaluator"
  | "guardrail"
  | "unknown";

export type SpanStatus = "OK" | "ERROR" | "UNSET";

export interface TraceSpan {
  id: string;
  parentId: string | null;
  name: string;
  /** Raw kind hint; semantic kind is derived via `deriveSpanKind` when absent. */
  kind?: string;
  /** Unix ns (bigint | numeric string) or ISO-8601 string. */
  startTime?: bigint | string;
  /** Absent/null = in-flight span (renders unbounded). */
  endTime?: bigint | string | null;
  status?: SpanStatus;
  model?: string;
  provider?: string;
  inputTokens?: number;
  outputTokens?: number;
  cacheReadTokens?: number;
  cacheCreationTokens?: number;
  ttftMs?: number;
  costUsd?: number;
  /** Raw input/output payloads (JSON string, chat array JSON, or plain text). */
  inputValue?: string;
  outputValue?: string;
  attributes?: Record<string, unknown>;
  events?: Array<{ name: string; time?: bigint | string; attributes?: Record<string, unknown> }>;
  children?: TraceSpan[];
}

/** One OpenAI-shaped tool call attached to an assistant message. */
export interface ToolCall {
  id: string;
  function?: { name?: string; arguments?: string };
}

/** ChatML message — the role vocabulary common to phoenix/langfuse/lens. */
export interface ChatMessage {
  role: string;
  content: unknown;
  tool_calls?: ToolCall[];
  tool_call_id?: string;
}

export interface FlatSpan {
  span: TraceSpan;
  depth: number;
}

/** Per-row micro-stats surfaced by the transcript feed. Missing inputs collapse to 0/null, never NaN. */
export interface TranscriptRowStats {
  inputTokens: number;
  outputTokens: number;
  costUsd: number;
  durationMs: number | null;
}

/** One row in the reader-mode transcript feed. */
export interface TranscriptRow {
  kind: "span" | "group-header";
  spanId: string;
  role?: string;
  preview?: string;
  stats?: TranscriptRowStats;
  groupId?: string;
}

/**
 * Timestamp normalization + duration math. Pure and total — never throws,
 * never does I/O. All internal math is bigint ns (ADR D2 of the plan): no
 * float precision loss on unix-ns timestamps.
 */

import type { SpanStatus, TraceSpan } from "@/lib/trace/types";

/**
 * Normalize a timestamp to unix ns. Accepts bigint ns, a numeric string
 * (treated as ns), or an ISO-8601 string (ms precision → ns). Returns null
 * for anything unparseable — callers treat null as "cannot place this span".
 */
export function toNs(value: bigint | string | null | undefined): bigint | null {
  if (typeof value === "bigint") return value;
  if (typeof value !== "string" || value === "") return null;
  try {
    return BigInt(value);
  } catch {
    const ms = Date.parse(value);
    return Number.isNaN(ms) ? null : BigInt(ms) * 1_000_000n;
  }
}

/** Span duration in ms; null when unavailable or clock-skewed (end < start). */
export function durationMs(span: Pick<TraceSpan, "startTime" | "endTime">): number | null {
  const start = toNs(span.startTime);
  const end = toNs(span.endTime ?? null);
  if (start === null || end === null) return null;
  const ms = (end - start) / 1_000_000n;
  return ms < 0n ? null : Number(ms);
}

/** Whether a span status counts as an error. Total: unknown statuses are not errors. */
export function isSpanError(status: SpanStatus | string | undefined): boolean {
  return status === "ERROR";
}

/** Compact ms/s/min duration label (`1500 → "1.5s"`). Null → "in-flight". Pure, no locale. */
export function formatDurationMs(ms: number | null): string {
  if (ms === null) return "in-flight";
  if (ms >= 60_000) return `${trimZeros(ms / 60_000)}min`;
  if (ms >= 1000) return `${trimZeros(ms / 1000)}s`;
  return `${Math.round(ms)}ms`;
}

function trimZeros(n: number): string {
  return Number.parseFloat(n.toFixed(2)).toString();
}

/**
 * ChatML detection + payload pretty-print. Pure and total. Output is ALWAYS
 * plain text/data — nothing here interprets HTML (the transcript/IO renderers
 * inherit the no-dangerouslySetInnerHTML invariant from these totals).
 */

import type { ChatMessage } from "@/lib/trace/types";

/** Parse a value as a chat-message array (`[{role, content}, …]`) or null when it is not one. */
export function asChat(value: string): ChatMessage[] | null {
  try {
    const parsed: unknown = JSON.parse(value);
    if (
      Array.isArray(parsed) &&
      parsed.length > 0 &&
      parsed.every((m) => m !== null && typeof m === "object" && "role" in m && "content" in m)
    ) {
      return parsed as ChatMessage[];
    }
  } catch {
    /* not JSON → not chat */
  }
  return null;
}

/** Pretty-print a stringified value as JSON when parseable, else leave it raw. Always plain text. */
export function prettyValue(value: string): string {
  try {
    return JSON.stringify(JSON.parse(value), null, 2);
  } catch {
    return value;
  }
}

const REDACTED = "<REDACTED>";

/** True when a message's content is redacted OR is/contains redacted thinking/reasoning. Pure, total. */
export function isRedactedThinking(m: ChatMessage): boolean {
  if (m.content === REDACTED) return true;
  if (Array.isArray(m.content)) {
    return m.content.some((b) => {
      if (b === null || typeof b !== "object") return false;
      const block = b as Record<string, unknown>;
      const type = typeof block.type === "string" ? block.type : "";
      if (type === "redacted_thinking") return true;
      if (type === "thinking") {
        return block.thinking === REDACTED || block.thinking === undefined || block.thinking === "";
      }
      return false;
    });
  }
  return false;
}

/** Extract a plain-text body from a message's content (string, or joined text/thinking blocks). Total. */
export function contentText(content: unknown): string {
  if (typeof content === "string") return content;
  if (content === null || content === undefined) return "";
  if (Array.isArray(content)) {
    return content
      .map((b) => {
        if (typeof b === "string") return b;
        if (b !== null && typeof b === "object") {
          const block = b as Record<string, unknown>;
          if (typeof block.text === "string") return block.text;
          if (typeof block.thinking === "string") return block.thinking;
        }
        return "";
      })
      .filter(Boolean)
      .join("\n\n");
  }
  return JSON.stringify(content, null, 2);
}

/**
 * Per-span and subtree USD cost. Pure and total — missing/non-numeric costs
 * collapse to 0 (never NaN) so `∑` badges stay honest.
 */

import type { TraceSpan } from "@/lib/trace/types";

// Attribute keys (checked in order) a per-span cost may arrive under when not a promoted field.
const COST_ATTRIBUTE_KEYS = ["gen_ai.usage.cost", "gen_ai.usage.cost_usd", "cost_usd", "cost"];

/**
 * A single span's own USD cost: the promoted `costUsd` field, else the first
 * parseable cost attribute. Total: missing/non-numeric → 0 (never NaN);
 * negative costs floor to 0.
 */
export function spanCostUsd(span: TraceSpan): number {
  if (typeof span.costUsd === "number" && Number.isFinite(span.costUsd)) {
    return span.costUsd > 0 ? span.costUsd : 0;
  }
  const attrs = span.attributes ?? {};
  for (const key of COST_ATTRIBUTE_KEYS) {
    if (!(key in attrs)) continue;
    const raw = attrs[key];
    const n = typeof raw === "number" ? raw : typeof raw === "string" ? Number(raw) : Number.NaN;
    if (Number.isFinite(n)) return n > 0 ? n : 0;
  }
  return 0;
}

/** Sum a span's own cost + all descendants' (`∑`). Total: missing cost counts as 0, never NaN. */
export function aggregateCost(span: TraceSpan): number {
  let total = spanCostUsd(span);
  for (const c of span.children ?? []) total += aggregateCost(c);
  return total;
}

/**
 * Tree flattening + the reader-mode transcript row model. Pure and total.
 * `flattenVisible` order is the contract every renderer (tree, waterfall,
 * transcript) shares, so selection/keyboard indices agree across views.
 */

import { spanCostUsd } from "@/lib/trace/cost";
import { durationMs } from "@/lib/trace/duration";
import type { FlatSpan, TraceSpan, TranscriptRow } from "@/lib/trace/types";

/**
 * Above this many visible rows, renderers switch from the recursive path to
 * the react-virtual flat-list (blueprint Corner 2 Q9; langfuse uses 350, the
 * lens origin uses 200 — virtualization only when it earns its complexity).
 */
export const VIRTUALIZE_THRESHOLD = 200;

/** Depth-first flatten of ALL spans (ignores collapse) — resolve-by-id / envelope input. */
export function flattenAll(root: TraceSpan): TraceSpan[] {
  const out: TraceSpan[] = [root];
  for (const c of root.children ?? []) out.push(...flattenAll(c));
  return out;
}

/** Depth-first flatten of VISIBLE spans (a node in `collapsed` contributes no descendants). */
export function flattenVisible(root: TraceSpan, collapsed: Set<string>): FlatSpan[] {
  const out: FlatSpan[] = [];
  const walk = (span: TraceSpan, depth: number) => {
    out.push({ span, depth });
    if (!collapsed.has(span.id)) for (const c of span.children ?? []) walk(c, depth + 1);
  };
  walk(root, 0);
  return out;
}

// A span whose output preview is longer than this is sliced (the full body lives in the detail pane).
const TRANSCRIPT_PREVIEW_CHARS = 140;
// A node fanning out into ≥2 children is treated as a subagent subtree and gets a collapsible
// group-header row before its children (there is no reliable agent-kind signal in raw OTLP data).
const SUBAGENT_MIN_CHILDREN = 2;

/** A short, single-line preview of a span's output (empty string when absent — never a crash). */
function transcriptPreview(span: TraceSpan): string {
  const oneLine = (span.outputValue ?? "").replace(/\s+/g, " ").trim();
  return oneLine.length > TRANSCRIPT_PREVIEW_CHARS
    ? `${oneLine.slice(0, TRANSCRIPT_PREVIEW_CHARS)}…`
    : oneLine;
}

/**
 * Flatten a span tree into the ordered reader-mode transcript feed. Pre-order
 * walk so `span`-row order matches `flattenVisible`. A fan-out node emits a
 * `group-header` row BEFORE its child rows so the view can collapse the group.
 */
export function toTranscriptRows(root: TraceSpan): TranscriptRow[] {
  const rows: TranscriptRow[] = [];
  const walk = (span: TraceSpan) => {
    const children = span.children ?? [];
    rows.push({
      kind: "span",
      spanId: span.id,
      role: span.kind ?? span.name ?? "span",
      preview: transcriptPreview(span),
      stats: {
        inputTokens: span.inputTokens ?? 0,
        outputTokens: span.outputTokens ?? 0,
        costUsd: spanCostUsd(span),
        durationMs: durationMs(span),
      },
    });
    if (children.length >= SUBAGENT_MIN_CHILDREN) {
      rows.push({ kind: "group-header", spanId: span.id, groupId: span.id });
    }
    for (const c of children) walk(c);
  };
  walk(root);
  return rows;
}

/**
 * Waterfall-layout math: trace time envelope, per-span bar geometry, a
 * human-friendly time axis, overlapping-span row packing, and ∑-cost
 * aggregation. Every function is pure and total — it NEVER throws and NEVER
 * does I/O — so skew / missing-timestamp / overlap / degenerate-bounds
 * negative cases are provable without rendering.
 */

import { toNs } from "@/lib/trace/duration";
import { flattenAll } from "@/lib/trace/flatten";
import type { TraceSpan } from "@/lib/trace/types";

/**
 * Trace time bounds — min start / max end across ALL spans (ns, bigint-safe):
 * the honest envelope for the waterfall denominator (not root-only, which
 * would let a child overflow). Unparseable timestamps are skipped; a trace
 * with no timestamps returns 0/0.
 */
export function computeTraceBounds(root: TraceSpan): { startNs: bigint; endNs: bigint } {
  let start: bigint | null = null;
  let end: bigint | null = null;
  for (const span of flattenAll(root)) {
    const s = toNs(span.startTime);
    if (s === null) continue;
    if (start === null || s < start) start = s;
    // A valid start always counts even when the end is missing/unparseable.
    const e = toNs(span.endTime ?? null) ?? s;
    const eff = e >= s ? e : s;
    if (end === null || eff > end) end = eff;
  }
  const s = start ?? 0n;
  return { startNs: s, endNs: end ?? s };
}

export interface BarLayout {
  leftPct: number;
  widthPct: number;
  unbounded: boolean;
}

/**
 * Map a span's [start, end] against the trace bounds → clamped {leftPct,
 * widthPct} in [0,100] with `leftPct + widthPct ≤ 100`. Missing end and
 * clock-skew (end < start) are flagged `unbounded` with zero width — never a
 * throw. Percentages carry 2 decimals via integer bigint math.
 */
export function computeBarLayout(
  spanStart: bigint | string | undefined,
  spanEnd: bigint | string | null | undefined,
  traceStartNs: bigint,
  traceEndNs: bigint,
): BarLayout {
  const window = traceEndNs > traceStartNs ? traceEndNs - traceStartNs : 1n; // div-by-zero guard
  const start = toNs(spanStart);
  if (start === null) return { leftPct: 0, widthPct: 0, unbounded: true };
  const end = toNs(spanEnd ?? null);
  const skewed = end !== null && end < start;
  const unbounded = end === null || skewed;
  const effEnd = end !== null && !skewed ? end : start;
  const pct = (delta: bigint) => (delta > 0n ? Number((delta * 10_000n) / window) / 100 : 0);
  const leftPct = Math.min(Math.max(pct(start - traceStartNs), 0), 100);
  const rawWidth = effEnd > start ? pct(effEnd - start) : 0;
  const widthPct = Math.min(Math.max(rawWidth, 0), 100 - leftPct);
  return { leftPct, widthPct, unbounded };
}

/** One tick on the waterfall time axis. */
export interface AxisTick {
  offsetNs: bigint;
  label: string;
  leftPct: number;
}

// The 1/2/5×10ⁿ "nice number" ladder — the mantissas step size snaps to.
const NICE_MANTISSAS = [1n, 2n, 5n];
const MIN_TICK_PX = 70; // ≥70px between ticks so labels never collide

/** Render a number with at most 2 decimals and no trailing zeros. */
function trimZeros(n: number): string {
  return Number.parseFloat(n.toFixed(2)).toString();
}

/** Format a nanosecond offset as a compact ms / s / min label by magnitude. Pure, no locale. */
function labelForNs(offsetNs: bigint): string {
  const ns = Number(offsetNs);
  if (ns >= 60_000_000_000) return `${trimZeros(ns / 60_000_000_000)}min`;
  if (ns >= 1_000_000_000) return `${trimZeros(ns / 1_000_000_000)}s`;
  return `${trimZeros(ns / 1_000_000)}ms`;
}

/** The smallest 1/2/5×10ⁿ step ≥ `targetNs`. Pure integer ladder walk (no Math.log rounding traps). */
function niceStep(targetNs: number): bigint {
  if (!(targetNs > 0)) return 0n;
  let pow = 1n;
  for (let guard = 0; guard < 32; guard++) {
    for (const m of NICE_MANTISSAS) {
      const candidate = m * pow;
      if (Number(candidate) >= targetNs) return candidate;
    }
    pow *= 10n;
  }
  return pow; // unreachable in practice; a total fallback rather than a throw
}

/**
 * Human-friendly time axis: pick a step from the 1/2/5×10ⁿ ladder so ticks
 * sit ≥70px apart, then emit ticks at 0, step, 2·step, … across the span.
 * Total: a degenerate window or non-positive width yields an empty axis.
 */
export function niceAxisTicks(startNs: bigint, endNs: bigint, pxWidth: number): AxisTick[] {
  if (endNs <= startNs || !(pxWidth > 0)) return [];
  const spanNs = endNs - startNs;
  const maxTicks = Math.max(1, Math.floor(pxWidth / MIN_TICK_PX));
  const step = niceStep(Number(spanNs) / maxTicks);
  if (step <= 0n) return [];
  const ticks: AxisTick[] = [];
  const spanNum = Number(spanNs);
  for (let offset = 0n; offset <= spanNs; offset += step) {
    ticks.push({
      offsetNs: offset,
      label: labelForNs(offset),
      leftPct: (Number(offset) / spanNum) * 100,
    });
  }
  return ticks;
}

/**
 * Greedy single-pass row packing for overlapping spans: sort by start, then
 * assign each span the lowest row whose last-placed span ended at/before this
 * span's start. Returns `Map<id, rowIndex>`. Total: `[]` → empty map.
 */
export function packRows(
  spans: Array<{ id: string; startNs: bigint; endNs: bigint }>,
): Map<string, number> {
  const rows = new Map<string, number>();
  const rowEnds: bigint[] = [];
  const ordered = [...spans].sort((a, b) =>
    a.startNs < b.startNs ? -1 : a.startNs > b.startNs ? 1 : 0,
  );
  for (const s of ordered) {
    // A skewed span (end < start) occupies a point at its start so it never covers a later row.
    const end = s.endNs >= s.startNs ? s.endNs : s.startNs;
    let placed = -1;
    for (let r = 0; r < rowEnds.length; r++) {
      const rowEnd = rowEnds[r];
      if (rowEnd !== undefined && rowEnd <= s.startNs) {
        placed = r;
        break;
      }
    }
    if (placed === -1) {
      placed = rowEnds.length;
      rowEnds.push(end);
    } else {
      rowEnds[placed] = end;
    }
    rows.set(s.id, placed);
  }
  return rows;
}

/**
 * PURE, deterministic layered layout for the agent-graph view. No I/O, no
 * React: derives each span's semantic kind, lays the trace out as a layered
 * node-edge graph (depth = distance from root, order = index within depth),
 * flags the root→selected execution path, and caps huge traces — so the SVG
 * renderer stays thin. SVG-pure by ADR D4 of the blueprint (no elkjs/d3).
 */

import { isSpanError } from "@/lib/trace/duration";
import { flattenAll } from "@/lib/trace/flatten";
import type { SpanKind, TraceSpan } from "@/lib/trace/types";

function attr(span: TraceSpan, key: string): string | undefined {
  const a = span.attributes;
  if (a == null || typeof a !== "object") return undefined;
  const v = (a as Record<string, unknown>)[key];
  return typeof v === "string" ? v : undefined;
}

/**
 * Derive a span's semantic kind from OTel GenAI signals (the raw `.kind`
 * field is often the OTLP numeric — useless as agent/tool/LLM). Precedence:
 * tool > retriever > embedding > llm > chain(has children) > unknown.
 */
export function deriveSpanKind(span: TraceSpan): SpanKind {
  const operationName = attr(span, "gen_ai.operation.name");
  const toolName = attr(span, "gen_ai.tool.name");
  const hasChildren = (span.children?.length ?? 0) > 0;
  if (toolName != null || operationName === "execute_tool") return "tool";
  if (operationName === "retrieve" || operationName === "search") return "retriever";
  if (operationName === "embeddings" || operationName === "embedding") return "embedding";
  if (operationName === "chat" || operationName === "text_completion" || span.model != null)
    return "llm";
  if (hasChildren) return "chain";
  return "unknown";
}

/** Above this span count the graph renders an honest "too large" state. */
export const GRAPH_NODE_CAP = 200;

// Deterministic order/depth grid spacing (px) — the SVG viewport scales to fit.
const NODE_X_GAP = 168;
const NODE_Y_GAP = 96;

export interface GraphNode {
  spanId: string;
  name: string;
  kind: SpanKind;
  depth: number;
  order: number;
  x: number;
  y: number;
  error: boolean;
  selected: boolean;
  onPath: boolean;
}
export interface GraphEdge {
  from: string;
  to: string;
  onPath: boolean;
}
export interface LayeredGraph {
  nodes: GraphNode[];
  edges: GraphEdge[];
  width: number;
  height: number;
  truncated: boolean;
  count: number;
}

/**
 * Build the deterministic layered graph. Edges come from parent/call order
 * (`parentId`), NOT the nested `children[]`, so malformed inputs are honest:
 * a self-loop or cycle is broken by a visited set; a span whose `parentId`
 * is absent from the trace is attached under the root, never dropped.
 * `onPath` = root→selected ancestor chain; with no selection, root→deepest
 * leaf. Over `cap` spans → `{ truncated: true, nodes: [], edges: [] }`.
 */
export function buildLayeredGraph(
  root: TraceSpan,
  selectedId?: string,
  cap = GRAPH_NODE_CAP,
): LayeredGraph {
  // Dedup by id (a malformed tree may repeat a span) — first occurrence wins.
  const seenIds = new Set<string>();
  const all = flattenAll(root).filter((s) => {
    if (seenIds.has(s.id)) return false;
    seenIds.add(s.id);
    return true;
  });
  const count = all.length;
  if (count > cap) {
    return { nodes: [], edges: [], width: 0, height: 0, truncated: true, count };
  }
  const byId = new Map(all.map((s) => [s.id, s]));

  // Effective parent: valid, non-self, present — else the root.
  const parentOf = new Map<string, string>();
  const childrenOf = new Map<string, string[]>();
  for (const s of all) {
    if (s.id === root.id) continue;
    const p = s.parentId;
    const eff = p != null && p !== s.id && byId.has(p) ? p : root.id;
    parentOf.set(s.id, eff);
    let bucket = childrenOf.get(eff);
    if (!bucket) {
      bucket = [];
      childrenOf.set(eff, bucket);
    }
    bucket.push(s.id);
  }

  // BFS from root → depth + order, with a visited guard (cycle-safe).
  const depthOf = new Map<string, number>();
  const orderOf = new Map<string, number>();
  const perDepth = new Map<number, number>();
  const visited = new Set<string>([root.id]);
  const queue: Array<{ id: string; depth: number }> = [{ id: root.id, depth: 0 }];
  let maxDepth = 0;
  while (queue.length > 0) {
    const item = queue.shift();
    if (!item) break;
    const order = perDepth.get(item.depth) ?? 0;
    perDepth.set(item.depth, order + 1);
    depthOf.set(item.id, item.depth);
    orderOf.set(item.id, order);
    maxDepth = Math.max(maxDepth, item.depth);
    for (const child of childrenOf.get(item.id) ?? []) {
      if (visited.has(child)) continue;
      visited.add(child);
      queue.push({ id: child, depth: item.depth + 1 });
    }
  }

  // Re-attach any node BFS never reached (cycle excluding the root) under the
  // root at depth 1 — an honest degraded view, shown + connected, never piled.
  for (const s of all) {
    if (depthOf.has(s.id)) continue;
    const order = perDepth.get(1) ?? 0;
    perDepth.set(1, order + 1);
    depthOf.set(s.id, 1);
    orderOf.set(s.id, order);
    parentOf.set(s.id, root.id);
    maxDepth = Math.max(maxDepth, 1);
  }

  const pathSet = new Set(computePath(root.id, selectedId, parentOf, depthOf, byId));

  const nodes: GraphNode[] = all.map((s) => {
    const depth = depthOf.get(s.id) ?? 0;
    const order = orderOf.get(s.id) ?? 0;
    return {
      spanId: s.id,
      name: s.name,
      kind: deriveSpanKind(s),
      depth,
      order,
      x: order * NODE_X_GAP,
      y: depth * NODE_Y_GAP,
      error: isSpanError(s.status),
      selected: selectedId != null && s.id === selectedId,
      onPath: pathSet.has(s.id),
    };
  });
  const edges: GraphEdge[] = all
    .filter((s) => s.id !== root.id)
    .map((s) => {
      const from = parentOf.get(s.id) ?? root.id;
      return { from, to: s.id, onPath: pathSet.has(from) && pathSet.has(s.id) };
    });

  const width = Math.max(1, ...Array.from(perDepth.values())) * NODE_X_GAP;
  const height = (maxDepth + 1) * NODE_Y_GAP;
  return { nodes, edges, width, height, truncated: false, count };
}

/** The ancestor chain root→selected; with no selection, root→deepest-leaf (BFS-order tie-break). */
function computePath(
  rootId: string,
  selectedId: string | undefined,
  parentOf: Map<string, string>,
  depthOf: Map<string, number>,
  byId: Map<string, TraceSpan>,
): string[] {
  let target = selectedId != null && byId.has(selectedId) ? selectedId : undefined;
  if (target === undefined) {
    let deepest = rootId;
    let best = -1;
    for (const [id, d] of depthOf) {
      if (d > best) {
        best = d;
        deepest = id;
      }
    }
    target = deepest;
  }
  const chain: string[] = [];
  const seen = new Set<string>();
  let cur: string | undefined = target;
  while (cur != null && !seen.has(cur)) {
    seen.add(cur);
    chain.push(cur);
    if (cur === rootId) break;
    cur = parentOf.get(cur);
  }
  return chain;
}

/** Kind → display label. */
export const KIND_LABEL: Record<SpanKind, string> = {
  llm: "LLM",
  tool: "Tool",
  retriever: "Retriever",
  embedding: "Embedding",
  agent: "Agent",
  chain: "Chain",
  reranker: "Reranker",
  evaluator: "Evaluator",
  guardrail: "Guardrail",
  unknown: "Span",
};

/**
 * Pure grouping of OTel span attributes by namespace (the prefix before the
 * first `.`). Keys without a dot fall into the `general` namespace. Total —
 * never throws; deterministic insertion order preserved within a group.
 */

export interface AttributeGroup {
  namespace: string;
  entries: Array<[string, unknown]>;
}

/** Group attribute entries by their dotted-key namespace, sorted by namespace name. */
export function groupByNamespace(attrs: Record<string, unknown>): AttributeGroup[] {
  const buckets = new Map<string, Array<[string, unknown]>>();
  for (const [key, value] of Object.entries(attrs)) {
    const dot = key.indexOf(".");
    const ns = dot > 0 ? key.slice(0, dot) : "general";
    let bucket = buckets.get(ns);
    if (!bucket) {
      bucket = [];
      buckets.set(ns, bucket);
    }
    bucket.push([key, value]);
  }
  return [...buckets.entries()]
    .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
    .map(([namespace, entries]) => ({ namespace, entries }));
}

/**
 * Pure, total structural alignment + metric aggregation for comparing two
 * traces. Never throws (cycle-guarded), never does I/O. Deltas are honest: a
 * span present in only one trace has NO delta (never a fabricated 1:1 diff).
 */

import { aggregateCost } from "@/lib/trace/cost";
import { durationMs, isSpanError } from "@/lib/trace/duration";
import { flattenAll } from "@/lib/trace/flatten";
import type { TraceSpan } from "@/lib/trace/types";

export interface TraceMetrics {
  durationMs: number | null;
  totalTokens: number;
  costUsd: number;
  hasError: boolean;
  spanCount: number;
}

/** Aggregate whole-trace metrics: root duration, summed tokens/cost, any-error flag. Total. */
export function traceMetrics(root: TraceSpan): TraceMetrics {
  const all = flattenAll(root);
  let totalTokens = 0;
  let hasError = false;
  for (const s of all) {
    totalTokens += (s.inputTokens ?? 0) + (s.outputTokens ?? 0);
    if (isSpanError(s.status)) hasError = true;
  }
  return {
    durationMs: durationMs(root),
    totalTokens,
    costUsd: aggregateCost(root),
    hasError,
    spanCount: all.length,
  };
}

export interface NumericDelta {
  from: number | null;
  to: number | null;
  deltaPct: number | null;
}

export interface AlignDelta {
  durationMs?: NumericDelta;
  tokens?: NumericDelta;
  costUsd?: NumericDelta;
}

export interface AlignRow {
  key: string;
  depth: number;
  a?: TraceSpan;
  b?: TraceSpan;
  status: "matched" | "only-in-a" | "only-in-b";
  /** Present ONLY when status === "matched" — an unpaired span has no honest delta. */
  delta?: AlignDelta;
}

function numericDelta(from: number | null, to: number | null): NumericDelta {
  const deltaPct =
    from !== null && to !== null && from !== 0 ? ((to - from) / Math.abs(from)) * 100 : null;
  return { from, to, deltaPct };
}

function spanTokens(s: TraceSpan): number {
  return (s.inputTokens ?? 0) + (s.outputTokens ?? 0);
}

function computeDelta(a: TraceSpan, b: TraceSpan): AlignDelta {
  return {
    durationMs: numericDelta(durationMs(a), durationMs(b)),
    tokens: numericDelta(spanTokens(a), spanTokens(b)),
    costUsd: numericDelta(a.costUsd ?? 0, b.costUsd ?? 0),
  };
}

/**
 * Align two span trees structurally, matching children by name (greedy,
 * first-unused). Produces a flat, depth-annotated row list: matched pairs
 * carry a delta; only-in-a / only-in-b rows do not. Cycle-safe via a visited
 * set on span ids (a malformed self-referential tree cannot loop).
 */
export function alignSpanTrees(a: TraceSpan, b: TraceSpan): AlignRow[] {
  const rows: AlignRow[] = [];
  const seen = new Set<string>();

  const walk = (an: TraceSpan | undefined, bn: TraceSpan | undefined, depth: number) => {
    const anchor = an ?? bn;
    if (!anchor) return;
    // Cycle guard: never revisit a span id from either side.
    const guardId = `${an?.id ?? ""}|${bn?.id ?? ""}`;
    if (seen.has(guardId)) return;
    seen.add(guardId);

    const status: AlignRow["status"] = an && bn ? "matched" : an ? "only-in-a" : "only-in-b";
    rows.push({
      key: anchor.name,
      depth,
      a: an,
      b: bn,
      status,
      delta: an && bn ? computeDelta(an, bn) : undefined,
    });

    const aChildren = an?.children ?? [];
    const bChildren = bn?.children ?? [];
    const bUsed = new Set<number>();
    for (const ac of aChildren) {
      if (ac.id === an?.id) continue; // self-loop child
      const j = bChildren.findIndex((bc, idx) => !bUsed.has(idx) && bc.name === ac.name);
      if (j >= 0) {
        bUsed.add(j);
        walk(ac, bChildren[j], depth + 1);
      } else {
        walk(ac, undefined, depth + 1);
      }
    }
    for (let idx = 0; idx < bChildren.length; idx++) {
      if (!bUsed.has(idx) && bChildren[idx]?.id !== bn?.id)
        walk(undefined, bChildren[idx], depth + 1);
    }
  };

  walk(a, b, 0);
  return rows;
}

